-- FormaPoint: iznosi u centima, transakcijske operacije i zadano zatvoren pristup.
create extension if not exists pgcrypto;
create type public.order_state as enum ('received','quote_pending','quote_sent','deposit_pending','ready','in_progress','needs_info','work_done','final_pending','delivered','revision','completed','cancelled');
create table public.profiles(id uuid primary key references auth.users on delete cascade,first_name text not null default '',last_name text not null default '',phone text,marketing_consent boolean not null default false,terms_accepted_at timestamptz,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid references auth.users on delete cascade,role text check(role in('CUSTOMER','ADMIN','STAFF','SUPPORT')) not null default 'CUSTOMER',primary key(user_id,role));
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role='ADMIN')$$;
create table public.service_categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,created_at timestamptz not null default now());
create table public.services(id uuid primary key default gen_random_uuid(),category_id uuid references public.service_categories,name text not null check(length(name) between 2 and 150),slug text not null unique check(slug ~ '^[a-z0-9-]+$'),category text not null,description text not null,icon text not null default 'FileText',price_cents integer check(price_cents between 100 and 100000000),unit_label text not null default 'zadatak',delivery_days integer not null default 0 check(delivery_days>=0),revisions integer not null default 1 check(revisions>=0),split_enabled boolean not null default false,split_min_cents integer not null default 10000 check(split_min_cents>=200),active boolean not null default true,popular boolean not null default false,included text[] not null default '{}',excluded text[] not null default '{}',sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.service_price_history(id uuid primary key default gen_random_uuid(),service_id uuid references public.services,old_cents integer,new_cents integer,actor uuid references auth.users,created_at timestamptz not null default now());
create table public.service_variants(id uuid primary key default gen_random_uuid(),service_id uuid not null references public.services,name text not null,price_cents integer not null check(price_cents>=100));
create table public.service_options(id uuid primary key default gen_random_uuid(),service_id uuid not null references public.services,name text not null);
create table public.service_option_values(id uuid primary key default gen_random_uuid(),option_id uuid not null references public.service_options,name text not null,price_cents integer not null check(price_cents>=0));
create table public.carts(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users on delete cascade,created_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts on delete cascade,service_id uuid not null references public.services,quantity integer not null default 1 check(quantity between 1 and 100),unique(cart_id,service_id),created_at timestamptz not null default now());
create sequence public.order_number_seq;
create table public.orders(id uuid primary key default gen_random_uuid(),number text not null unique default ('FP-'||to_char(now() at time zone 'Europe/Zagreb','YYYY')||'-'||lpad(nextval('public.order_number_seq')::text,6,'0')),user_id uuid not null references auth.users,title text not null check(length(title) between 3 and 150),description text not null check(length(description) between 10 and 10000),status public.order_state not null default 'received',total_cents integer check(total_cents between 100 and 100000000),paid_cents integer not null default 0 check(paid_cents>=0),payment_model text not null default 'full' check(payment_model in('full','split')),due_at timestamptz,download_override boolean not null default false,created_at timestamptz not null default now());
create index orders_user on public.orders(user_id,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,service_id uuid references public.services,name text not null,quantity integer not null check(quantity between 1 and 100),unit_cents integer check(unit_cents>=0));
create table public.quotes(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,version integer not null,total_cents integer not null check(total_cents between 100 and 100000000),description text not null check(length(description) between 10 and 10000),currency text not null default 'EUR' check(currency='EUR'),expires_at timestamptz not null,due_at timestamptz not null,split_enabled boolean not null default false,accepted_at timestamptz,rejected_at timestamptz,created_at timestamptz not null default now(),unique(order_id,version));
create table public.quote_items(id uuid primary key default gen_random_uuid(),quote_id uuid not null references public.quotes,description text not null,amount_cents integer not null check(amount_cents>=0));
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,status public.order_state not null,actor_id uuid references auth.users,created_at timestamptz not null default now());
create table public.order_files(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,uploader_id uuid not null references auth.users,name text not null,path text not null unique,kind text not null check(kind in('attachment','preview','final')),size integer not null check(size between 1 and 20971520),scan_status text not null default 'quarantined' check(scan_status in('quarantined','clean','rejected')),version integer not null default 1,created_at timestamptz not null default now());
create table public.order_messages(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,sender_id uuid not null references auth.users,body text not null check(length(body) between 1 and 5000),internal boolean not null default false,created_at timestamptz not null default now());
create index messages_order on public.order_messages(order_id,created_at);
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,installment integer not null check(installment in(1,2)),amount_cents integer not null check(amount_cents>=1),refunded_cents integer not null default 0 check(refunded_cents>=0 and refunded_cents<=amount_cents),fee_cents integer check(fee_cents>=0),currency text not null default 'EUR' check(currency='EUR'),provider text not null default 'stripe' check(provider in('stripe','bank')),status text not null default 'pending' check(status in('pending','succeeded','failed','refunded','partially_refunded','expired')),provider_session_id text unique,provider_payment_id text unique,attempt integer not null default 1,created_at timestamptz not null default now());
create unique index one_active_installment on public.payments(order_id,installment) where status in('pending','succeeded','partially_refunded','refunded');
create table public.payment_installments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,installment integer not null check(installment in(1,2)),amount_cents integer not null check(amount_cents>=0),unique(order_id,installment));
create table public.payment_provider_events(id text primary key,provider text not null,type text not null,processed_at timestamptz not null default now());
create table public.refunds(id text primary key,payment_id uuid not null references public.payments,amount_cents integer not null check(amount_cents>0),status text not null,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.notification_preferences(user_id uuid primary key references auth.users,email_enabled boolean not null default true,created_at timestamptz not null default now());
create table public.notification_outbox(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,notification_id uuid not null references public.notifications,status text not null default 'pending' check(status in('pending','sending','sent','failed')),attempts integer not null default 0,locked_at timestamptz,last_error text,created_at timestamptz not null default now());
create table public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,subject text not null check(length(subject) between 3 and 150),category text not null check(category in('Narudžbe','Plaćanja','Datoteke','Tehnički problem','Povrat novca','Ostalo','Izvoz podataka','Brisanje računa')),body text not null check(length(body) between 10 and 10000),status text not null default 'open' check(status in('open','in_progress','closed')),created_at timestamptz not null default now());
create table public.support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets,sender_id uuid not null references auth.users,body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create table public.contact_requests(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 2 and 150),email text not null check(length(email) between 3 and 254),body text not null check(length(body) between 10 and 5000),created_at timestamptz not null default now());
create table public.promo_codes(id uuid primary key default gen_random_uuid(),code text not null unique,kind text not null check(kind in('percent','fixed')),value integer not null check(value>0),max_uses integer not null check(max_uses>0),expires_at timestamptz not null,service_id uuid references public.services,active boolean not null default true,check(kind<>'percent' or value<=100),created_at timestamptz not null default now());
create table public.promo_code_uses(id uuid primary key default gen_random_uuid(),promo_id uuid not null references public.promo_codes,user_id uuid not null references auth.users,order_id uuid not null references public.orders,unique(promo_id,user_id));
create table public.invoices_metadata(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders,external_reference text,document_kind text not null,official boolean not null default false,created_at timestamptz not null default now());
create table public.business_settings(id boolean primary key default true check(id),legal_name text,address text,contact_email text,tax_status text,created_at timestamptz not null default now());
create table public.site_settings(id boolean primary key default true check(id),stripe_enabled boolean not null default false,bank_enabled boolean not null default false,maintenance boolean not null default true,created_at timestamptz not null default now());
insert into public.site_settings(id)values(true);insert into public.business_settings(id)values(true);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid,action text not null,entity_id text,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,window_at timestamptz not null default now(),hits integer not null default 1);
create function public.owns_order(order_id uuid)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.orders where id=order_id and user_id=auth.uid())$$;
create function public.assert_user()returns uuid language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'Prijava je potrebna';end if;return auth.uid();end$$;
create function public.assert_admin()returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Nemate ovlasti';end if;end$$;
create function public.rate_limit(k text,max_hits integer,seconds integer) returns void language plpgsql security definer set search_path=public as $$declare n integer;begin insert into public.rate_limits(key)values(k)on conflict(key)do update set hits=case when rate_limits.window_at<now()-make_interval(secs=>seconds)then 1 else rate_limits.hits+1 end,window_at=case when rate_limits.window_at<now()-make_interval(secs=>seconds)then now() else rate_limits.window_at end returning hits into n;if n>max_hits then raise exception 'Previše zahtjeva. Pokušajte kasnije.';end if;end$$;
create function public.on_signup()returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,first_name,last_name,phone,marketing_consent,terms_accepted_at)values(new.id,left(coalesce(new.raw_user_meta_data->>'first_name',''),150),left(coalesce(new.raw_user_meta_data->>'last_name',''),150),left(new.raw_user_meta_data->>'phone',40),coalesce((new.raw_user_meta_data->>'marketing_consent')::boolean,false),now());insert into public.user_roles values(new.id,'CUSTOMER');insert into public.notification_preferences(user_id)values(new.id);return new;end$$;
create trigger user_signup after insert on auth.users for each row execute function public.on_signup();
create function public.audit_change()returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.audit_logs(actor_id,action,entity_id)values(auth.uid(),tg_table_name||'.'||tg_op,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'));if tg_table_name='services' and tg_op='UPDATE' then if old.price_cents is distinct from new.price_cents then insert into public.service_price_history(service_id,old_cents,new_cents,actor)values(new.id,old.price_cents,new.price_cents,auth.uid());end if;end if;return coalesce(new,old);end$$;
do $$declare t text;begin foreach t in array array['services','service_categories','orders','quotes','payments','promo_codes','site_settings','business_settings','user_roles','order_files','support_tickets']loop execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.audit_change()',t);end loop;end$$;
create function public.order_event()returns trigger language plpgsql security definer set search_path=public as $$declare n uuid;begin if tg_op='INSERT' or new.status is distinct from old.status then insert into public.order_status_history(order_id,status,actor_id)values(new.id,new.status,auth.uid());insert into public.notifications(user_id,title,body)values(new.user_id,'Ažuriranje narudžbe '||new.number,'Otvorite narudžbu za pregled novog statusa.')returning id into n;insert into public.notification_outbox(user_id,notification_id)values(new.user_id,n);end if;return new;end$$;
create trigger order_event after insert or update on public.orders for each row execute function public.order_event();
-- RLS: nijedan korisnik ne može sam mijenjati narudžbu, uplatu ili ulogu.
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='public'loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid()or public.is_admin());
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid())with check(id=auth.uid());
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid()or public.is_admin());
create policy services_read on public.services for select using(active or public.is_admin());
create policy services_admin on public.services for all to authenticated using(public.is_admin())with check(public.is_admin());
create policy categories_read on public.service_categories for select using(true);
create policy categories_admin on public.service_categories for all to authenticated using(public.is_admin())with check(public.is_admin());
create policy orders_read on public.orders for select to authenticated using(user_id=auth.uid()or public.is_admin());
create policy cart_read on public.carts for select to authenticated using(user_id=auth.uid());
create policy cart_items_read on public.cart_items for select to authenticated using(exists(select 1 from public.carts where id=cart_id and user_id=auth.uid()));
create policy messages_read on public.order_messages for select to authenticated using(public.is_admin()or(public.owns_order(order_id)and not internal));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid())with check(user_id=auth.uid());
create policy preferences_all on public.notification_preferences for all to authenticated using(user_id=auth.uid())with check(user_id=auth.uid());
create policy tickets_read on public.support_tickets for select to authenticated using(user_id=auth.uid()or public.is_admin());
create policy support_messages_read on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and(t.user_id=auth.uid()or public.is_admin())));
do $$declare t text;begin foreach t in array array['quotes','order_items','order_status_history','order_files','payments','payment_installments','invoices_metadata']loop execute format('create policy order_owner_read on public.%I for select to authenticated using(public.owns_order(order_id)or public.is_admin())',t);end loop;foreach t in array array['service_price_history','contact_requests','promo_codes','promo_code_uses','audit_logs','notification_outbox','business_settings','payment_provider_events','refunds']loop execute format('create policy admin_read on public.%I for select to authenticated using(public.is_admin())',t);end loop;foreach t in array array['promo_codes','site_settings','business_settings']loop execute format('create policy admin_write on public.%I for all to authenticated using(public.is_admin())with check(public.is_admin())',t);end loop;end$$;
create policy site_read on public.site_settings for select using(true);
-- Storage: nema izravnog SELECT pristupa, čak ni vlasniku; download Edge Function izdaje kratki URL.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('order-files','order-files',false,20971520,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/plain','image/jpeg','image/png']);
-- Prava se dodjeljuju eksplicitno; RPC funkcije dodatno provjeravaju identitet.
revoke all on all tables in schema public from anon,authenticated;
grant select on public.services,public.service_categories,public.site_settings to anon,authenticated;
grant select on all tables in schema public to authenticated;
grant update(first_name,last_name,phone,marketing_consent)on public.profiles to authenticated;
grant update(read_at)on public.notifications to authenticated;
grant insert,update on public.notification_preferences to authenticated;
grant insert,update,delete on public.services,public.service_categories,public.promo_codes to authenticated;
grant update on public.site_settings,public.business_settings to authenticated;
